<script setup lang="ts">
/**
 * A Button preset for signing in with an identity provider (`design/components/provider-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/provider-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { BrandMark, Icon, agentMember, agentPress } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/provider-button.module.css'

export type ProviderButtonProvider = ProviderButtonProps['provider']

export interface ProviderButtonProps {
  /**
   * Links supporting text, such as "Your organization requires single sign-on", to the button.
   */
  ariaDescribedby?: string
  disabled?: boolean
  /**
   * The full label in the app's language, such as "Continue with Google". It is required and
   * passed whole, because the vocabulary has no built-in text, word order around a brand name
   * differs by language, and the provider's terms govern the wording.
   */
  label: string
  /**
   * The sign-in flow has started and not finished. Keeps focus, colours and name, and ignores
   * presses.
   */
  loading?: boolean
  /**
   * Which mark is drawn, from `BrandMark`'s fixed set.
   */
  provider: 'google' | 'microsoft' | 'github'
  size?: 'sm' | 'md' | 'lg'
  type?: 'button' | 'submit'
}

defineOptions({ name: 'ProviderButton', inheritAttrs: false })

const props = withDefaults(defineProps<ProviderButtonProps>(), {
  disabled: false,
  loading: false,
  size: 'md',
  type: 'button',
})
const emit = defineEmits<{ click: [event: MouseEvent] }>()
const control = useTemplateRef<HTMLElement>('control')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ProviderButton',
    element: () => control.value,
    state: () => ({ disabled: props.disabled, loading: props.loading }),
    actions: { press: () => agentPress(control.value) },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <button
    ref="control"
    :class="styles.button"
    :type="type"
    :disabled="disabled"
    :aria-busy="loading ? true : undefined"
    :aria-describedby="ariaDescribedby"
    data-variant="outline"
    data-tone="neutral"
    :data-size="size"
    :data-state="loading ? 'loading' : undefined"
    :data-disabled="disabled ? '' : undefined"
    :data-provider="provider"
    data-member="provider-button"
    @click="!loading && emit('click', $event)"
  >
    <!-- spinner -->
    <span v-if="loading" :class="styles.spinner">
      <Icon name="loading" :size="size" />
    </span>
    <!-- mark -->
    <span v-else :class="styles.mark">
      <component :is="BrandMark" :name="provider" :size="size" />
    </span>
    <!-- label -->
    <span :class="styles.label">
      {{ label }}
    </span>
  </button>
</template>
